export function isMacOS(): boolean {
  const userAgent = navigator.userAgent.toLowerCase();
  const isMac = /(iphone|ipad|ipod|macintosh)/i.test(userAgent);
  const isTouchDevice = userAgent.includes("mac") && "ontouchend" in document;
  
  return isMac && isTouchDevice;
}
